local config = {
  str_homestory_N17guide_90000101_1_dialog_content = "...",
  str_homestory_N17guide_90000101_2_dialog_content = "Hmm…",
  str_homestory_N17guide_90000101_3_dialog_content = "Vice?",
  str_homestory_N17guide_90000101_4_dialog_content = "Lihat apa kau?",
  str_homestory_N17guide_90000101_5_dialog_content = "Negeri yang luas sekali... Aku tak menyangka Eraveil punya tempat seperti ini!",
  str_homestory_N17guide_90000101_6_dialog_content = "Kok kita bisa tidak menyadarinya sepanjang petualangan ini?!",
  str_homestory_N17guide_90000101_7_dialog_content = "Kau juga tak ingat? Lagi pula, ini adalah kampung halamanmu...",
  str_homestory_N17guide_90000101_8_option_content = "Ingat.",
  str_homestory_N17guide_90000101_9_dialog_content = "Kalau harus bilang, kurasa aku sedikit ingat tempat ini. Bangunan dan flora di sini terasa cukup familier.",
  str_homestory_N17guide_90000101_10_dialog_content = "Tapi, aku tak begitu yakin... Mungkin aku keliru.",
  str_homestory_N17guide_90000101_11_dialog_content = "Lagi pula, ini bukan Eraveil yang sama seperti yang kita kenal, jadi mungkin ingatanku tak begitu tepat.",
  str_homestory_N17guide_90000101_12_dialog_content = "Benar, kau masih sangat kecil saat itu, dan tempat ini sangat tersembunyi...",
  str_homestory_N17guide_90000101_13_option_content = "Tak ingat.",
  str_homestory_N17guide_90000101_14_dialog_content = "Sepertinya aku belum pernah melihat tempat ini.",
  str_homestory_N17guide_90000101_15_dialog_content = "Ingatan samar yang kumiliki adalah tentang tempat lain di Eraveil. Kurasa aku belum pernah ke sini saat masih kecil.",
  str_homestory_N17guide_90000101_16_dialog_content = "Benar, tempat ini sangat tersembunyi.",
  str_homestory_N17guide_90000101_17_dialog_content = "Eraveil benar-benar misterius. Selalu ada kejutan yang menanti kita.",
  str_homestory_N17guide_90000101_18_dialog_content = "Aku tidak sabar ingin menjelajahi tempat ini!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000101_19_dialog_content = "Apa jiwa Exploration Team Illumina telah bangkit kembali?",
  str_homestory_N17guide_90000101_20_dialog_content = "Krak, krak...",
  str_homestory_N17guide_90000101_21_dialog_content = "Hah? Apa itu?",
  str_homestory_N17guide_90000101_22_dialog_content = "Ini terlihat seperti semacam mesin... otomatis? Atau makhluk?",
  str_homestory_N17guide_90000101_23_dialog_content = "Chubb, Chubb!",
  str_homestory_N17guide_90000101_24_dialog_content = "Ia berbicara!",
  str_homestory_N17guide_90000101_25_dialog_content = "Selamat datang, selamat datang! Chubb! Chubb!",
  str_homestory_N17guide_90000101_26_dialog_content = "Ia tampak sangat bahagia. Kukira itu perangkat pertahanan yang akan menandai kita sebagai musuh.",
  str_homestory_N17guide_90000101_27_dialog_content = "Kalau tidak salah, ia terbuat dari teknologi Caelestite. Lihat saja dari kualitasnya...",
  str_homestory_N17guide_90000101_28_dialog_content = "Lihat juga tanda di atasnya... Sepertinya aku pernah melihat tanda seperti itu di Colossus.",
  str_homestory_N17guide_90000101_29_dialog_content = "Kenapa penampilannya konyol begitu?",
  str_homestory_N17guide_90000101_30_dialog_content = "Chubb!! Siapa yang kau sebut konyol, Chubb!!<sprite=emo_nuhuo size=60 />",
  str_homestory_N17guide_90000101_31_dialog_content = "Ia marah. Kelihatannya kecil, tapi mudah marah.",
  str_homestory_N17guide_90000101_32_dialog_content = "Mari lihat sekeliling. Boleh kami meminta izinmu untuk mengunjungi tempat ini?",
  str_homestory_N17guide_90000101_33_dialog_content = "Eh... Aku harus memanggilmu apa?",
  str_homestory_N17guide_90000101_34_dialog_content = "Chubb.",
  str_homestory_N17guide_90000101_35_dialog_content = "... Chubb? Apa kau baru saja memberinya nama?",
  str_homestory_N17guide_90000101_36_dialog_content = "Ia terus berkata \"Chubb\".",
  str_homestory_N17guide_90000101_37_dialog_content = "Chubb! Nama yang bagus, Chubb!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000101_38_dialog_content = "Ia menyukai nama ini?",
  str_homestory_N17guide_90000101_39_dialog_content = "Kurasa ia sudah menerima kita!",
  str_homestory_N17guide_90000101_40_dialog_content = "Ayo, PlayerName! Mari lihat sekeliling!",
  str_homestory_N17guide_90000102_0_dialog_content = "Vice…",
  str_homestory_N17guide_90000102_1_dialog_content = "PlayerName, aku sudah berbicara dengan Chubb.",
  str_homestory_N17guide_90000102_2_dialog_content = "Aku punya pemahaman sedikit tentangnya... Sebenarnya sangat sederhana!",
  str_homestory_N17guide_90000102_3_dialog_content = "Apa? Kau bahkan mengobrol dengannya?",
  str_homestory_N17guide_90000102_4_dialog_content = "Ia belajar bahasa Universese dengan sangat cepat. Ia bahkan memberiku <color=#FFB400>kapak</color> dan <color=#FFB400>gancu</color>.",
  str_homestory_N17guide_90000102_5_dialog_content = "Kapak dan gancu?",
  str_homestory_N17guide_90000102_6_dialog_content = "Tepat. Sepertinya untuk menebang? Atau menggali?<sprite=emo_sikao size=60 />",
  str_homestory_N17guide_90000102_7_dialog_content = "Bagaimanapun, kurasa ia butuh bantuan kita untuk mengumpulkan beberapa <color=#FFB400>material</color>.",
  str_homestory_N17guide_90000102_8_dialog_content = "Mungkin untuk memperbaiki bangunan di sini?",
  str_homestory_N17guide_90000102_9_dialog_content = "Omong-omong, aku akan menyerahkannya kepadamu, PlayerName. Gunakan itu sebagai kesempatan untuk melatih dirimu sendiri.<sprite=emo_dianzan size=60 />",
  str_homestory_N17guide_90000102_10_dialog_content = "Aku bahkan tak punya kesempatan untuk menolak.<sprite=emo_xiaoku size=60 />",
  str_homestory_N17guide_90000102_11_dialog_content = "Aku sudah membuat rangkuman tentang beberapa hal yang disampaikan Chubb kepadaku, dan mencatatnya di <color=#FFB400>manual</color> ini.",
  str_homestory_N17guide_90000102_12_dialog_content = "Cepat sekali!",
  str_homestory_N17guide_90000103_1_dialog_content = "Chubb! Perbaikan selesai! Hore! Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000103_2_dialog_content = "Cepat sekali! Apa yang baru saja terjadi?",
  str_homestory_N17guide_90000103_3_dialog_content = "Sepertinya ia memperbaiki meja kerja di <color=#FFB400>Hyacinth Tower</color>! Luar biasa!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000103_4_dialog_content = "Ini bukan masalah besar, Chubb...<sprite=emo_guilian size=60 />",
  str_homestory_N17guide_90000103_5_dialog_content = "Hyacinth Tower? Apakah kau yang memberinya nama itu?",
  str_homestory_N17guide_90000103_6_dialog_content = "Tidak. Bukankah kita melihat yang lebih besar di Eraveil sebelumnya?",
  str_homestory_N17guide_90000103_7_dialog_content = "Keduanya terlihat sangat serupa bagiku. Sama-sama menara juga. Jadi, aku menamakannya Hyacinth Tower!",
  str_homestory_N17guide_90000103_8_dialog_content = "Tapi, menara di depan kita ini jelas jauh lebih bagus. Aku ingin tahu apa fungsinya...",
  str_homestory_N17guide_90000103_9_dialog_content = "Bagaimana kalau kau coba saja sendiri? Chubb!",
  str_homestory_N17guide_90000103_10_dialog_content = "Jika dioperasikan oleh si Caelestite ini, menaranya pasti akan berfungsi, Chubb!",
  str_homestory_N17guide_90000103_11_dialog_content = "Benarkah? Akan kucoba kalau begitu!",
  str_homestory_N17guide_90000103_12_dialog_content = "PlayerName, Chubb ingin kau mencoba meja kerjanya!",
  str_homestory_N17guide_90000103_13_dialog_content = "Sepertinya ia memperlakukanmu seperti master di tempat ini.",
  str_homestory_N17guide_90000103_14_dialog_content = "Master...",
  str_homestory_N17guide_90000103_15_dialog_content = "Chubb, Chubb.",
  str_homestory_N17guide_90000103_16_dialog_content = "...",
  str_homestory_N17guide_90000103_17_dialog_content = "Ya, aku master di tempat ini sekarang.",
  str_homestory_N17guide_90000103_18_dialog_content = "Maaf sudah lama... dan membuatmu menunggu, Chubb.",
  str_homestory_N17guide_90000103_19_dialog_content = "Aku kembali!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000103_20_dialog_content = "Kau kembali! Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000103_21_dialog_content = "Jadi, sebagai master di tempat ini, apa kau berencana untuk mengundang kawan-kawan yang lain?",
  str_homestory_N17guide_90000103_22_dialog_content = "Tentu saja! Tapi, di mana mereka akan tinggal begitu tiba di sini?",
  str_homestory_N17guide_90000103_23_dialog_content = "Kau bisa menggunakan meja kerja untuk membangun <color=#FFB400>Gardens Dorm</color>! Chubb!",
  str_homestory_N17guide_90000103_24_dialog_content = "Ada <color=#FFB400>asrama</color> di sini! Tempat ini benar-benar memiliki fasilitas yang lengkap!",
  str_homestory_N17guide_90000103_25_dialog_content = "Mari kita mencobanya!",
  str_homestory_N17guide_90000104_1_dialog_content = "<sprite=emo_hanshui size=60 />Fiuh... selesai sudah!",
  str_homestory_N17guide_90000104_2_dialog_content = "Tak kusangka membangun ternyata semudah itu. Kukira akan memakan waktu yang sangat lama.",
  str_homestory_N17guide_90000104_3_dialog_content = "Omong-omong, begitu juga halnya di Colossus. Hanya butuh waktu sekejap untuk menyelesaikan renovasi ruangan di sana.",
  str_homestory_N17guide_90000104_4_dialog_content = "Inikah kekuatan teknologi? Caelestite memang luar biasa.",
  str_homestory_N17guide_90000104_5_dialog_content = "Bukankah begitu, Vi—",
  str_homestory_N17guide_90000104_6_dialog_content = "Vice?<sprite=emo_yihuo size=60 />",
  str_homestory_N17guide_90000104_7_dialog_content = "Sebelah sini, PlayerName!",
  str_homestory_N17guide_90000104_8_dialog_content = "Aku sudah tidak sabar mengajak yang lain datang kemari!",
  str_homestory_N17guide_90000104_9_dialog_content = "Cepatlah dan <color=#FFB400>undang</color> mereka kemari!",
  str_homestory_N17guide_90000104_10_dialog_content = "Ya, baiklah!",
  str_homestory_N17guide_90000105_1_dialog_content = "Halo, Ms. Blanc. Selamat datang di...",
  str_homestory_N17guide_90000105_2_dialog_content = "Anu…",
  str_homestory_N17guide_90000105_3_dialog_content = "... <color=#FFB400>Cloud Gardens</color> milikku.",
  str_homestory_N17guide_90000105_4_dialog_content = "Hah? Kau cukup pandai mengarang nama dengan cepat, ya, PlayerName.",
  str_homestory_N17guide_90000105_5_dialog_content = "Aku punya guru yang baik.<sprite=emo_guilian size=60 />",
  str_homestory_N17guide_90000105_6_dialog_content = "Cloud Gardens... Mengesankan, nama yang bagus.",
  str_homestory_N17guide_90000105_7_dialog_content = "Pemandangan di sini juga menakjubkan. Aku bahkan bisa melupakan sementara semua masalahku selama berada di sini...",
  str_homestory_N17guide_90000105_8_dialog_content = "Aku berterima kasih dari lubuk hati yang paling dalam karena sudah mengundangku ke sini, PlayerName.",
  str_homestory_N17guide_90000105_9_dialog_content = "Jangan sungkan, Ms. Blanc. Kita sudah berteman lama di petualangan ini, dan kita juga harus bertani bersama...",
  str_homestory_N17guide_90000105_10_dialog_content = "Ehem!<sprite=emo_shengqi size=60 />",
  str_homestory_N17guide_90000105_11_dialog_content = "Oh, maksudku menikmati pemandangannya bersama!",
  str_homestory_N17guide_90000105_12_dialog_content = "Haha! Tidak apa-apa! Aku akan melakukan tugasku demi mengembangkan Cloud Gardens.",
  str_homestory_N17guide_90000105_13_dialog_content = "Aku juga akan mencari tahu tentang lingkungan di sini agar bisa jadi pemandu yang lebih baik bagi pengunjung lain.",
  str_homestory_N17guide_90000105_14_dialog_content = "Bisa beri tahu aku tentang fasilitas lainnya, PlayerName?",
  str_homestory_N17guide_90000105_15_dialog_content = "Biar kujelaskan, Ms. Blanc. Chubb baru saja memberitahuku lebih banyak!",
  str_homestory_N17guide_90000105_16_dialog_content = "Karena <color=#FFB400>Hyacinth Tower</color> secara bertahap sedang disempurnakan, kita bisa menggunakan meja kerjanya untuk <color=#FFB400>membuka lebih banyak bangunan</color>.",
  str_homestory_N17guide_90000105_17_dialog_content = "<color=#FFB400>Gardens Dorm</color> yang baru saja kita selesaikan bisa menampung semua orang yang berkunjung!",
  str_homestory_N17guide_90000105_18_dialog_content = "Selain itu, ada <color=#FFB400>Fountain of Hope</color>, air mancur di depan Hyacinth Tower.",
  str_homestory_N17guide_90000105_19_dialog_content = "Tempat ini punya banyak kejutan untuk semua orang, dan akan membuat kita ingin selalu mengunjunginya!",
  str_homestory_N17guide_90000105_20_dialog_content = "Ada <color=#FFB400>museum</color> juga. Harta karun langka yang kita peroleh akan dipajang di sana...",
  str_homestory_N17guide_90000105_21_dialog_content = "Oh, masih ada lagi…",
  str_homestory_N17guide_90000105_22_dialog_content = "Vice, pelan-pelan. Ms. Blanc tak bisa memproses semua itu dengan cepat...",
  str_homestory_N17guide_90000105_23_dialog_content = "Benar juga... Perlahan membiasakan diri dengan pendekatan secara langsung terdengar seperti rencana yang bagus.",
  str_homestory_N17guide_90000105_24_dialog_content = "PlayerName, yakin itu bukan karena kau yang tak bisa mengingat semuanya?",
  str_homestory_N17guide_90000105_25_dialog_content = "<sprite=emo_xuanyun size=60 />I-Ini memang sedikit membuatku kewalahan...",
  str_homestory_N17guide_90000105_26_dialog_content = "Aku harus mengingat fungsi tiap bangunan, lalu bersiap untuk menyambut semua orang...",
  str_homestory_N17guide_90000105_27_dialog_content = "Aku tak tahu harus bagaimana menghadapimu. Kalau begitu, rawat tempat ini dengan baik...",
  str_homestory_N17guide_90000105_28_dialog_content = "Kau bisa menggunakan <color=#FFB400>buku harian</color> ini untuk mencatat keseharianmu di Cloud Gardens!",
  str_homestory_N17guide_90000105_29_dialog_content = "Catat semua yang terjadi di sini sehingga kau tak akan bingung ketika saatnya tiba!",
  str_homestory_N17guide_90000105_30_dialog_content = "Kau sungguh penuh perhatian, Vice.",
  str_homestory_N17guide_90000105_31_dialog_content = "PlayerName, jika kau merasa lelah, aku tahu cara paling sempurna untuk membantumu bersantai!",
  str_homestory_N17guide_90000105_32_dialog_content = "Hah? Apa itu?",
  str_homestory_N17guide_90000105_33_dialog_content = "Hehe, ikuti aku jika ingin tahu!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000106_0_dialog_content = "Hah?",
  str_homestory_N17guide_90000106_1_dialog_content = "Vice! Apakah caramu untuk bersantai...",
  str_homestory_N17guide_90000106_2_dialog_content = "Benar sekali! Ini <color=#FFB400>memancing</color>!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000106_3_dialog_content = "Tak ada yang lebih menenangkan dari menikmati kesenangan memancing di tempat yang begitu indah.",
  str_homestory_N17guide_90000106_4_dialog_content = "(Lagi pula... ikan yang kita tangkap bisa <color=#FFB400>dijual</color>.)<sprite=emo_baiyebi size=60 />",
  str_homestory_N17guide_90000106_5_dialog_content = "(Vice! Aku bisa merasakan obsesimu terhadap uang!)",
  str_homestory_N17guide_90000106_6_dialog_content = "<sprite=emo_hanshui size=60 />B-Bukan itu intinya... Omong-omong, ayo kita coba memancing!!",
  str_homestory_N17guide_90000106_7_dialog_content = "Ini jorannya! Waktunya bekerja!",
  str_homestory_N17guide_90000106_8_dialog_content = "Aku melihat ada sekop. Untuk apa itu?",
  str_homestory_N17guide_90000106_9_dialog_content = "Oh, selain memancing, aku berencana menggali di sekitar sini. Siapa tahu aku menemukan harta karun.",
  str_homestory_N17guide_90000106_10_dialog_content = "Kau terang-terangan mengungkapkan niatmu untuk menghasilkan uang.",
  str_homestory_N17guide_90000106_11_dialog_content = "<sprite=emo_shengqi size=60 />Bukankah kita sudah menjelajahi area ini? Ini namanya berburu harta karun! Berburu harta karun!",
  str_homestory_N17guide_90000106_12_dialog_content = "Tak perlu khawatir jika kau tersesat. Lihat saja <color=#FFB400>petamu</color>.",
  str_homestory_N17guide_90000106_13_dialog_content = "Baiklah, kalau begitu saatnya memancing!",
  str_homestory_N17guide_90000107_1_dialog_content = "Woah! Tokonya sudah siap! Suasananya makin hidup di sini!",
  str_homestory_N17guide_90000107_2_dialog_content = "Benar sekali, Chubb! Kita sudah siap berjualan, Chubb!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000107_3_dialog_content = "Hebatnya, Chubb dalam berbagai penampilan yang berbeda akan bertanggung jawab atas berbagai macam fasilitas...",
  str_homestory_N17guide_90000107_4_dialog_content = "Imut sekali. Aku bahkan berpikir untuk membawa pulang satu ke Lumopolis!<sprite=emo_aixin size=60 />",
  str_homestory_N17guide_90000107_5_dialog_content = "Chu-Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000107_6_dialog_content = "Jadi, aku bisa mulai menghasilkan uang sekarang?",
  str_homestory_N17guide_90000107_7_dialog_content = "Ya, aku punya semua informasi yang kau butuhkan.",
  str_homestory_N17guide_90000107_8_dialog_content = "Toko secara rutin akan memajang segala jenis <color=#FFB400>pesanan</color>. Kau akan diberi imbalan setelah menyelesaikannya.",
  str_homestory_N17guide_90000107_9_dialog_content = "Menghasilkan uang tanpa perlu melangkah keluar! Cloud Gardens memang luar biasa!!<sprite=emo_dianzan size=60 />",
  str_homestory_N17guide_90000107_10_dialog_content = "Aku tak mengira ada toko kecil tapi lengkap di sini...",
  str_homestory_N17guide_90000107_11_dialog_content = "Aku bahkan lebih terkesan dengan Cloud Gardens sekarang...",
  str_homestory_N17guide_90000107_12_dialog_content = "Cobalah, PlayerName! Mari selesaikan pesanan sebagai permulaan!",
  str_homestory_N17guide_90000107_13_dialog_content = "Baiklah!",
  str_homestory_N17guide_90000107_14_dialog_content = "Sebenarnya, kenapa aku selalu bekerja dengan sangat antusias di mana-mana?<sprite=emo_tanqi size=60 />",
  str_homestory_N17guide_90000107_15_dialog_content = "Ini adalah rumahmu sendiri, PlayerName! Ayo, semangat!",
  str_homestory_N17guide_90000108_0_dialog_content = "Selesai!",
  str_homestory_N17guide_90000108_1_dialog_content = "Woah! Imbalannya lumayan juga!<sprite=emo_baiyebi size=60 />",
  str_homestory_N17guide_90000108_2_dialog_content = "Senang rasanya bisa menghasilkan uang dengan usahaku sendiri!",
  str_homestory_N17guide_90000108_3_dialog_content = "Kita sudah menyiapkan kios dan memenuhi permintaan sebelumnya, 'kan? Aku bahkan mengajak bertarung semua orang di Umbraton setiap hari.",
  str_homestory_N17guide_90000108_4_dialog_content = "Ini beda! Membangun Cloud Gardens adalah pengalaman baru bagiku!",
  str_homestory_N17guide_90000108_5_dialog_content = "Oh, aku ingin tahu apakah ada yang lebih baik...",
  str_homestory_N17guide_90000108_6_dialog_content = "Tentu saja.",
  str_homestory_N17guide_90000108_7_dialog_content = "Benarkah? Kenapa kau bisa tahu begitu banyak tentang tempat ini?<sprite=emo_yihuo size=60 />",
  str_homestory_N17guide_90000108_8_dialog_content = "Kau bisa mencoba <color=#FFB400>menanam pohon</color>.",
  str_homestory_N17guide_90000108_9_dialog_content = "Pohon-pohon di sini harus ditanam? Kukira pohonnya tumbuh secara alami...",
  str_homestory_N17guide_90000108_10_dialog_content = "Bukan pohon biasa. Ini...",
  str_homestory_N17guide_90000108_11_dialog_content = "Ini adalah <color=#FFB400>Unique Tree</color> spesial. Kau bahkan harus menyiapkan area <color=#FFB400>Land of Fertility</color> khusus untuk pohon ini.",
  str_homestory_N17guide_90000108_12_dialog_content = "Benarkah? Kalau begitu, bagaimana kalau kita mencobanya?",
  str_homestory_N17guide_90000108_13_dialog_content = "Aku agak lelah. Aku mau kembali ke Hyacinth Tower untuk memeriksa laporan keuangan.",
  str_homestory_N17guide_90000108_14_dialog_content = "Vice! Menanam pohon itu pekerjaan fisik!",
  str_homestory_N17guide_90000108_15_dialog_content = "Teknologi Caelestite sangat maju. Tak perlu melakukan kerja fisik.<sprite=emo_qingsong size=60 />",
  str_homestory_N17guide_90000108_16_dialog_content = "Eh...",
  str_homestory_N17guide_90000109_1_dialog_content = "Bagus, PlayerName!<sprite=emo_caitiao size=60 />",
  str_homestory_N17guide_90000109_2_dialog_content = "Cloud Gardens berkembang jadi begitu indah dengan cepat!",
  str_homestory_N17guide_90000109_3_dialog_content = "Chubb, Chubb, Chubb!<sprite=emo_yinfu size=60 />",
  str_homestory_N17guide_90000109_4_dialog_content = "Kau juga, Vice! Kau selalu ada untuk menjelaskan semuanya kepadaku.",
  str_homestory_N17guide_90000109_5_dialog_content = "Vice, memahami bahasa Chubb itu sangat sulit, 'kan?",
  str_homestory_N17guide_90000109_6_dialog_content = "Meski begitu, kau memintaku membantu PlayerName untuk menyambut datangnya Aurorian lainnya.",
  str_homestory_N17guide_90000109_8_dialog_content = "Jadi, kau tidak bermalas-malasan, Vice.",
  str_homestory_N17guide_90000109_9_dialog_content = "Tentu saja! Ini rumah baru kita! Aku harus merawat tempat ini dengan baik!",
  str_homestory_N17guide_90000109_10_dialog_content = "Selain itu, aku perlu menghitung pendapatan dan pengeluaran baru, dan pengeluaran rutin kita di Colossus tak bisa diabaikan...",
  str_homestory_N17guide_90000109_11_dialog_content = "Oh, perlukah kita memasang sejumlah papan reklame untuk Umbraton di Cloud Gardens dan menyewakannya?<sprite=emo_tanqi size=60 />",
  str_homestory_N17guide_90000109_12_option_content = "Tolak",
  str_homestory_N17guide_90000109_13_dialog_content = "T-Tidak! Tentu tidak!",
  str_homestory_N17guide_90000109_14_dialog_content = "Aku hanya bercanda! Aku tak akan merusak rumah tersayang PlayerName!",
  str_homestory_N17guide_90000109_15_option_content = "Setuju",
  str_homestory_N17guide_90000109_16_dialog_content = "Ya, tempat ini sangat besar. Jika kita bisa memasang sejumlah papan reklame...",
  str_homestory_N17guide_90000109_17_dialog_content = "Aku hanya bercanda. Melakukan hal itu akan menjadikan tempat ini Umbraton kedua.",
  str_homestory_N17guide_90000109_18_dialog_content = "Aku tak tega merusak rumah tersayang PlayerName!",
  str_homestory_N17guide_90000109_19_dialog_content = "Kita harus merawat semua yang ada di tempat ini dengan baik, dan membuat Cloud Gardens makin indah!",
  str_homestory_N17guide_90000109_20_dialog_content = "Kami siap, Chubb!",
  str_homestory_N17guide_90000109_21_dialog_content = "Vice sangat pandai dalam hal ini. Bahkan aku jadi merasa bersemangat.",
  str_homestory_N17guide_90000109_22_dialog_content = "PlayerName, kudengar ada banyak jenis furnitur, bangunan, dan pohon luar biasa yang menunggu untuk ditemukan di Cloud Gardens.",
  str_homestory_N17guide_90000109_23_dialog_content = "Mungkin suatu hari, kita bisa menjadikan tempat ini surga di Astra?",
  str_homestory_N17guide_90000109_24_dialog_content = "Tentu saja bisa!",
  str_homestory_N17guide_90000109_25_dialog_content = "Kalau begitu ayo kita bekerja keras meraih tujuan itu!",
  str_homestory_N17guide_90000109_26_dialog_content = "Satu, dua, tiga…",
  str_homestory_N17guide_90000109_27_dialog_content = "Ayo kita lakukan!!<sprite=emo_laba size=60 />"
}
